<template><div class="min-h-full bg-background p-3 md:p-4"><div class="mx-auto max-w-5xl"><div class="mb-3 flex items-center justify-between"><button @click="goBack" class="inline-flex items-center gap-1.5 border border-slate-300 bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 hover:border-primary hover:text-primary">← Back</button><span class="text-[10px] font-semibold uppercase tracking-wide text-slate-400">Bank financing detail</span></div><div v-if="error" class="border border-red-200 bg-red-50 p-3 text-xs text-red-700">{{error}}</div><div v-else class="border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-200 px-4 py-3"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h1 class="mt-0.5 text-lg font-bold text-slate-900">{{item.bank_name||'Bank financing'}}</h1></div><button @click="editOpen=true" class="border border-primary px-3 py-1.5 text-xs font-semibold text-primary">Edit</button></div><div class="grid gap-2 p-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="(v,k) in financingFields" :key="k" class="min-h-14 border border-slate-200 px-3 py-2"><p class="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{{label(k)}}</p><p class="mt-0.5 text-xs font-semibold text-slate-900">{{format(v)}}</p></div></div><div v-if="application" class="border-t border-slate-200 p-3"><div class="mb-2 flex items-center justify-between"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Application</p><p class="text-sm font-semibold text-slate-900">{{customerName(application.customer)}}</p></div><button @click="viewApplication" class="border border-slate-300 px-3 py-1.5 text-[11px] font-semibold text-slate-700 hover:border-primary hover:text-primary">View application detail</button></div><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><div v-for="(v,k) in applicationSummary" :key="k" class="min-h-14 border border-slate-200 px-3 py-2"><p class="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{{label(k)}}</p><p class="mt-0.5 text-xs font-semibold text-slate-900">{{v||'—'}}</p></div></div></div></div></div><EditOffplanBankFinancing :open="editOpen" :id="id" @close="editOpen=false" @saved="load"/></div></template>
<script>import EditOffplanBankFinancing from "./EditOffplanBankFinancing.vue";export default{name:"OffplanBankFinancingDetail",components:{EditOffplanBankFinancing},props:{id:[String,Number]},data(){return{item:{},error:"",editOpen:false}},computed:{application(){return this.item.application&&typeof this.item.application==="object"?this.item.application:null},financingFields(){const x=this.item;return{bank_name:x.bank_name,loan_account_number:x.loan_account_number,loan_amount:x.loan_amount,interest_rate:x.interest_rate,loan_term_months:x.loan_term_months,monthly_payment:x.monthly_payment,loan_status:x.loan_status,approved_at:x.approved_at,first_payment_date:x.first_payment_date,notes:x.notes}},applicationSummary(){const a=this.application,p=a?.offplan_property,z=p?.property_zone;return{customer:this.customerName(a?.customer),developer:p?.developer||"—",offplan_property:this.propertyName(p),property_zone:z?.name||"—",owner:this.customerName(a?.owner)||"—"}}},mounted(){this.load()},methods:{async load(){try{const r=await this.$apiGetById("/get_offplan_bank_financing",this.id);this.item=r?.data?.data||r?.data||r?.financing||r}catch(e){this.error=e?.message||"Unable to load financing."}},customerName(v){if(!v)return"—";if(typeof v==="string")return v;return[v.first_name,v.middle_name,v.last_name].filter(Boolean).join(" ")||v.name||v.username||"—"},propertyName(p){if(!p)return"—";return p.name||p.title||p.property_name||p.property_type||"Offplan property"},label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},format(v){return v??"—"},goBack(){this.$router.back()},viewApplication(){const aid=this.application?.id;if(aid)this.$router.push({name:"OffplanApplication-detail",params:{id:aid}})}}};</script>